    "~/Library/Logs/app.sitin.desktop",
    "~/Library/Preferences/app.sitin.desktop.plist",
    "~/Library/Saved Application State/app.sitin.desktop.savedState",
    "~/Library/WebKit/app.sitin.desktop",
  ]

  caveats <<~EOS
    Sitin is a development build: ad-hoc signed and not notarized by Apple.
    This cask removes the quarantine attribute so macOS opens it without a prompt.
    The app updates itself; `brew upgrade --cask sitin` is not needed.
  EOS
